import { test, expect, type Page } from '@playwright/test';
import { mockPublicApi } from './fixtures/api-mock';
// REPARACION_8B4B
// REPARACION_8B4C
test.beforeEach(async({page})=>mockPublicApi(page));
async function abrirCatalogo(page:Page){await page.goto('/w2/torneos');await expect(page.locator('.w2t-card').first()).toBeVisible()}
async function abrirDetalleCurso(page:Page){await page.goto('/w2/torneos?torneo=2');await expect(page.locator('.premium-tournament-detail')).toBeVisible()}
async function abrirCentro(page:Page,vista='resumen'){await page.goto('/w2/torneos?torneo=2&categoria=11&vista='+vista);await expect(page.locator('.f4-center')).toBeVisible()}
async function activarVistaCentro(page:Page,vista:string){const boton=page.locator('[data-f4-view="'+vista+'"]');await expect(boton).toBeVisible();await boton.evaluate(elemento=>{elemento.scrollIntoView({block:'nearest',inline:'center'});(elemento as HTMLElement).click()})}
test('catálogo muestra estados, resumen y torneo destacado',async({page})=>{await abrirCatalogo(page);await expect(page.locator('#resumenTorneos')).toContainText('próxim');await expect(page.locator('#torneoDestacado')).toContainText('Torneo E2E');await page.getByRole('button',{name:/En curso/}).click();await expect(page.locator('#listaTorneos')).toContainText('Copa Metropolitana E2E')});
test('búsqueda y filtros producen resultados y permiten limpiar',async({page,isMobile})=>{await abrirCatalogo(page);await page.locator('#buscarTorneo').fill('inexistente');await expect(page.locator('.w2t-empty')).toBeVisible();await page.getByRole('button',{name:'Ver todos los torneos'}).click();await expect(page.locator('.w2t-card')).toHaveCount(1);if(isMobile){await page.locator('#abrirFiltrosTorneos').click();await expect(page.locator('#panelFiltrosTorneos')).toHaveClass(/open/);await page.locator('#cerrarFiltrosTorneos').click()}else{await expect(page.locator('#panelFiltrosTorneos')).toBeVisible();await expect(page.locator('#filtroRama')).toBeAttached()}});
test('detalle navega por información, categorías y reglamento actualizando URL',async({page})=>{await abrirDetalleCurso(page);await page.getByRole('tab',{name:/Categorías/}).click();await expect(page.locator('.premium-category-card')).toHaveCount(2);await expect(page).toHaveURL(/seccion=categorias/);await page.getByRole('tab',{name:'Reglamento',exact:true}).click();await expect(page.locator('.w2td-rules-content')).toContainText('mejor de tres sets');await expect(page).toHaveURL(/seccion=reglamento/)});
test('inscripción valida, envía el cuerpo y presenta confirmación',async({page})=>{let body:any;page.on('request',r=>{if(r.url().endsWith('/torneos/inscripciones')&&r.method()==='POST')body=r.postDataJSON()});await page.goto('/w2/torneos?torneo=1');await expect(page.locator('.premium-tournament-detail')).toBeVisible();await page.getByRole('tab',{name:/Categorías/}).click();await expect(page.locator('.premium-category-card')).toBeVisible();await page.locator('.inscribir-pareja').click();await page.locator('#enviarInscripcion').click();await expect(page.locator('#responsableNombre')).toBeFocused();await page.locator('#responsableNombre').fill('Facundo');await page.locator('#responsableApellido').fill('Vitale');await page.locator('#responsableTelefono').fill('1144445555');await page.locator('#parejaNombre').fill('Jugador');await page.locator('#parejaApellido').fill('E2E');await page.locator('#parejaTelefono').fill('1166667777');await page.locator('#comentariosInscripcion').fill('Prueba 8B.4');await page.locator('#enviarInscripcion').click();await expect(page.locator('#exitoInscripcion')).toContainText('#801');expect(body.torneoCategoriaId).toBe(11);expect(body.comentarios).toBe('Prueba 8B.4')});
test('centro competitivo abre directo y conserva parámetros URL',async({page})=>{await abrirCentro(page);await expect(page.locator('.f4-hero')).toContainText('4ta');await expect(page.locator('.f4-status-grid')).toContainText('Etapa eliminatoria');await expect(page).toHaveURL(/categoria=11/)});
test('posiciones cambia de grupo y presenta clasificación',async({page})=>{await abrirCentro(page,'posiciones');await expect(page.locator('.f4-standings')).toContainText('Grupo A');await page.locator('[data-f4-group="102"]').click();await expect(page.locator('.f4-standings')).toContainText('Grupo B');await expect(page).toHaveURL(/grupo=102/)});
test('partidos filtra por instancia y conserva el filtro',async({page})=>{await abrirCentro(page,'partidos');await expect(page.locator('.f4-match')).toHaveCount(5);await page.locator('[data-f4-phase="fase-final"]').click();await expect(page.locator('.f4-phase-section')).toContainText('Final');await expect(page).toHaveURL(/instancia=fase-final/)});
test('cuadro integrado navega entre rondas sin perder la vista',async({page,isMobile})=>{await abrirCentro(page,'cuadro');await expect(page.locator('.f4-round').first()).toContainText('Semifinal');if(isMobile){await page.locator('[data-f4-round="1"]').click();await expect(page.locator('.f4-round.mobile-active')).toContainText('Final')}else{await expect(page.locator('.f4-round')).toHaveCount(2);await expect(page.locator('.f4-round').nth(1)).toContainText('Final');await expect(page.locator('[data-f4-round="1"]')).toBeHidden()}await expect(page).toHaveURL(/vista=cuadro/)});
test('llave completa abre y cierra en escritorio, y no abre en móvil',async({page,isMobile})=>{await abrirCentro(page,'cuadro');const boton=page.locator('[data-f4-full-bracket]');if(isMobile){await expect(boton).toBeHidden();await expect(page.locator('#modalCuadroTorneo')).toHaveClass(/hidden/)}else{await boton.click();await expect(page.locator('#modalCuadroTorneo')).not.toHaveClass(/hidden/);await expect(page.locator('.bracket-card')).toHaveCount(3);await expect(page.locator('#escalaLlave')).toContainText('%');await page.locator('#cerrarCuadroTorneo').click();await expect(page.locator('#modalCuadroTorneo')).toHaveClass(/hidden/);await expect(boton).toBeFocused()}});
test('volver del centro restaura categorías y limpia el estado profundo',async({page})=>{await page.goto('/w2/torneos?torneo=2&categoria=11&vista=cuadro&grupo=101&instancia=fase-final&ronda=1');await expect(page.locator('.f4-center')).toBeVisible();await page.locator('[data-f4-back]').click();await expect(page.locator('.premium-category-card')).toHaveCount(2);await expect(page).toHaveURL(/seccion=categorias/);for(const parametro of ['categoria','vista','grupo','instancia','ronda'])await expect(page).not.toHaveURL(new RegExp('[?&]'+parametro+'='))});


test('F4.1 persiste ronda y restaura navegación',async({page,isMobile})=>{await abrirCentro(page,'cuadro');if(isMobile){await page.locator('[data-f4-round="1"]').click();await expect(page).toHaveURL(/ronda=1/);await page.reload();await expect(page.locator('.f4-round.mobile-active')).toContainText('Final');await page.goBack();await expect(page).not.toHaveURL(/ronda=1/)}else{await expect(page.locator('.f4-nav')).toHaveAttribute('role','tablist')}});

test('F4.1 permite teclado entre vistas y expone panel accesible',async({page})=>{await abrirCentro(page);const resumen=page.locator('[data-f4-view="resumen"]');await resumen.focus();await page.keyboard.press('ArrowRight');await expect(page.locator('[data-f4-view="posiciones"]')).toBeFocused();await expect(page.locator('[data-f4-view="posiciones"]')).toHaveAttribute('aria-selected','true');await expect(page.locator('#f4-panel')).toHaveAttribute('role','tabpanel');});

test('F4.1 evita refetch inmediato de una categoría cacheada',async({page})=>{let llamadas=0;page.on('request',r=>{if(r.url().includes('/torneos/categorias/11/competencia'))llamadas++});await abrirCentro(page);await page.locator('[data-f4-view="posiciones"]').click();await page.locator('[data-f4-view="resumen"]').click();expect(llamadas).toBe(1);});


test('la ruta anterior redirige al catálogo canónico W2',async({page})=>{await page.goto('/torneos');await expect(page).toHaveURL(url=>url.pathname==='/w2/torneos');await expect(page.locator('.w2t-card').first()).toBeVisible();await expect(page.locator('.tournament-v51')).toHaveCount(0)});

test('Torneos vive dentro del shell W2 y marca la navegación activa',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('[data-w2-header]')).toBeVisible();await expect(page.locator('.w2-links a.active')).toHaveText('Torneos');await expect(page.locator('.w2t-card').first()).toBeVisible()});


test('F4.1 normaliza categoría ajena y conserva el shell W2',async({page})=>{await page.goto('/w2/torneos?torneo=1&categoria=12&vista=cuadro&ronda=9');await expect(page.locator('.f4-load-error')).toContainText('Categoría no disponible');await expect(page.locator('[data-w2-header]')).toBeVisible()});

test('F4.1B presenta el catálogo con identidad nativa W2',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('.w2t-hero')).toBeVisible();await expect(page.locator('.w2t-featured')).toContainText('Torneo E2E');await expect(page.locator('.w2t-card').first()).toContainText('Inscripción por pareja');await expect(page.locator('.tournament-v51')).toHaveCount(0)});
test('F4.1B publica la rama heredada masculina como Libre en W2',async({page})=>{await page.goto('/w2/torneos');await page.getByRole('button',{name:/En curso/}).click();await expect(page.locator('.w2t-card').first()).toContainText('Libre')});
test('F4.1B3 usa selectores W2 con nombres públicos y teclado',async({page})=>{await page.goto('/w2/torneos');if((page.viewportSize()?.width||0)<900){await page.locator('#abrirFiltrosTorneos').click();await expect(page.locator('#panelFiltrosTorneos')).toBeVisible()}const rama=page.locator('.w2t-select').filter({has:page.locator('#filtroRama')});await rama.locator('.w2t-select-trigger').click();await expect(rama.locator('.w2t-select-menu')).toBeVisible();await expect(rama.locator('.w2t-select-menu')).toContainText('Libre');await expect(rama.locator('.w2t-select-menu')).not.toContainText('Masculina');await page.keyboard.press('End');await page.keyboard.press('Enter');await expect(rama.locator('.w2t-select-trigger')).toContainText('Mixto')});
test('F4.1B3 no presenta torneos vencidos como próximos',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('.w2t-card').filter({hasText:'Master Final E2E'})).toHaveCount(0);await page.getByRole('button',{name:/Finalizados/}).click();await expect(page.locator('#listaTorneos')).toContainText('Master Final E2E')});
test('F4.1C presenta el detalle nativo W2',async({page})=>{await page.goto('/w2/torneos?torneo=2');await expect(page.locator('.w2td-detail')).toBeVisible();await expect(page.locator('.w2td-hero')).toContainText('Copa Metropolitana E2E');await expect(page.locator('.w2td-summary')).toContainText('Parejas');await expect(page.locator('.premium-detail-hero')).toHaveCount(0)});
test('F4.1C muestra categorías con rama pública e inscripción por pareja',async({page})=>{await page.goto('/w2/torneos?torneo=2&seccion=categorias');await page.getByRole('tab',{name:/Categorías/}).click();const categoria=page.locator('.w2td-category').first();await expect(categoria).toContainText('Libre');await expect(categoria).toContainText(/Inscripción por pareja|Competencia iniciada/);await expect(categoria).not.toContainText('Masculina')});
test('la ruta anterior preserva navegación profunda y fragmento',async({page})=>{await page.goto('/torneos?torneo=2&categoria=11&vista=cuadro&ronda=1#definicion');await expect(page).toHaveURL(url=>url.pathname==='/w2/torneos'&&url.searchParams.get('torneo')==='2'&&url.searchParams.get('categoria')==='11'&&url.searchParams.get('vista')==='cuadro'&&url.searchParams.get('ronda')==='1'&&url.hash==='#definicion');await expect(page.locator('.f4-center')).toBeVisible();await expect(page.locator('.tournament-v51')).toHaveCount(0)});
test('F4.1C2 accesos rápidos llevan al contenido seleccionado',async({page})=>{await page.goto('/w2/torneos?torneo=1');await page.locator('[data-go-categories]').click();await expect(page).toHaveURL(/seccion=categorias/);await expect(page.locator('#premiumDetailContent')).toBeInViewport();await page.goto('/w2/torneos?torneo=1');await page.locator('[data-go-rules]').click();await expect(page).toHaveURL(/seccion=reglamento/);await expect(page.locator('#premiumDetailContent')).toBeInViewport()});
test('F4.2 presenta resumen competitivo nativo y compacto',async({page})=>{await abrirCentro(page);await expect(page.locator('.w2cc-center')).toBeVisible();await expect(page.locator('.w2cc-overview')).toContainText('Estado general de la competencia');await expect(page.locator('.w2cc-status-grid')).toContainText('Progreso');await expect(page.locator('.w2cc-dashboard')).toContainText('Próximos partidos');await expect(page.locator('.w2cc-dashboard')).toContainText('Resultados recientes')});
test('F4.2 traduce rama pública y enlaza resumen con Partidos',async({page})=>{await abrirCentro(page);await expect(page.locator('.w2cc-hero')).toContainText('Libre');await page.locator('.w2cc-activity [data-f4-view="partidos"]').first().click();await expect(page.locator('[data-f4-view="partidos"]')).toHaveAttribute('aria-selected','true');await expect(page).toHaveURL(/vista=partidos/)});
test('F4.2B aisla la navegacion sticky y publica Libre en la llave',async({page,isMobile})=>{await abrirCentro(page);await page.evaluate(()=>scrollTo(0,document.body.scrollHeight/3));const nav=page.locator('.w2cc-center .f4-nav');await expect(nav).toBeVisible();const fondo=await nav.evaluate(e=>{const s=getComputedStyle(e);return {imagen:s.backgroundImage,color:s.backgroundColor}});expect(fondo.imagen.includes('linear-gradient')||fondo.color!=='rgba(0, 0, 0, 0)').toBeTruthy();if(!isMobile){await page.locator('[data-f4-view="cuadro"]').click();await page.locator('[data-f4-full-bracket]').click();await expect(page.locator('#modalCuadroTorneo')).toContainText('Libre');await expect(page.locator('#modalCuadroTorneo')).not.toContainText('Masculina')}});
test('F4.3-F4.5 elimina la identidad verde estructural del centro W2',async({page,isMobile})=>{await abrirCentro(page,'posiciones');const grupo=page.locator('[data-f4-group="101"]');await expect(grupo).toHaveClass(/active/);const grupoColor=await grupo.evaluate(e=>getComputedStyle(e).borderColor);expect(grupoColor).not.toBe('rgb(76, 157, 117)');await activarVistaCentro(page,'partidos');const fase=page.locator('[data-f4-phase="fase-final"]');await fase.click();const faseColor=await fase.evaluate(e=>getComputedStyle(e).borderColor);expect(faseColor).not.toBe('rgb(74, 157, 117)');await activarVistaCentro(page,'cuadro');if(isMobile){await expect(page.locator('.f4-round.mobile-active')).toBeVisible();await expect(page.locator('.f4-bracket-actions')).toBeHidden()}else{await expect(page.locator('.f4-bracket-actions')).toBeVisible();await page.locator('[data-f4-full-bracket]').click();await expect(page.locator('#modalCuadroTorneo')).toContainText('Libre');const fondo=await page.locator('.bracket-viewport').evaluate(e=>getComputedStyle(e).backgroundColor);expect(fondo).not.toBe('rgb(11, 19, 22)')}});
test('F4.5C mantiene selector y ronda visibles durante la navegación móvil',async({page,isMobile})=>{if(!isMobile)return;await abrirCentro(page,'cuadro');for(const ronda of ['0','1','0','1']){await page.locator('[data-f4-round="'+ronda+'"]').click();await expect(page.locator('.f4-round-tabs')).toBeInViewport();await expect(page.locator('.f4-round.mobile-active')).toBeVisible();await expect(page.locator('[data-f4-round="'+ronda+'"]').first()).toHaveClass(/active/)}});test('F4.5B al abrir Cuadro deja visibles filtros y ronda activa en móvil',async({page,isMobile})=>{if(!isMobile)return;await abrirCentro(page,'partidos');await activarVistaCentro(page,'cuadro');await expect(page.locator('.f4-round-tabs')).toBeInViewport();await expect(page.locator('.f4-round.mobile-active')).toBeVisible();await expect(page.locator('[data-f4-view="cuadro"]')).toHaveAttribute('aria-selected','true')});
test('F4.5F la cabecera permanece estable y el verde no invade la estructura',async({page,isMobile})=>{await abrirCentro(page,'posiciones');const grupo=page.locator('[data-f4-group="101"]');await expect(grupo).toHaveClass(/active/);const bordeGrupo=await grupo.evaluate(e=>getComputedStyle(e).borderColor);expect(bordeGrupo).not.toBe('rgb(101, 185, 138)');if(isMobile){const header=page.locator('[data-w2-header]');await expect(header).toBeVisible();for(const vista of ['partidos','cuadro','posiciones']){await activarVistaCentro(page,vista);await expect(header).toBeVisible();await expect(header).toHaveCSS('visibility','visible')}}});
test('F4.6 normaliza la densidad del catálogo sin perder controles',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('.w2t-hero')).toBeVisible();await expect(page.locator('.w2t-featured')).toBeVisible();await expect(page.locator('.w2t-card').first()).toBeVisible();const boton=page.locator('.w2t-card').first().getByRole('button').last();await expect(boton).toBeVisible();const alto=await boton.evaluate(e=>e.getBoundingClientRect().height);expect(alto).toBeGreaterThanOrEqual(44)});
test('F4.6 compacta el detalle manteniendo pestañas y acciones táctiles',async({page})=>{await page.goto('/w2/torneos?torneo=1');await expect(page.locator('.w2td-hero')).toBeVisible();const tabs=page.locator('.premium-detail-tabs [role="tab"],.w2td-tabs [role="tab"]');await expect(tabs.first()).toBeVisible();const alto=await tabs.first().evaluate(e=>e.getBoundingClientRect().height);expect(alto).toBeGreaterThanOrEqual(44);await page.locator('[data-go-categories]').click();await expect(page.locator('.w2td-category').first()).toBeVisible()});
test('F4.6 no altera la escala estructural del centro competitivo',async({page})=>{await abrirCentro(page);await expect(page.locator('.w2cc-center')).toBeVisible();await expect(page.locator('.w2cc-hero')).toBeVisible();await expect(page.locator('.w2cc-overview')).toBeVisible()});
test('F4.6A la cabecera general permanece estable durante interacciones del centro',async({page})=>{await abrirCentro(page);const header=page.locator('[data-w2-header]');await expect(header).toBeVisible();for(const vista of ['posiciones','partidos','cuadro','resumen']){await activarVistaCentro(page,vista);await expect(header).toBeVisible();await expect(header).toHaveCSS('visibility','visible');await expect(header).toHaveCSS('opacity','1')}await activarVistaCentro(page,'posiciones');await page.locator('[data-f4-group="102"]').click();await expect(header).toBeVisible()});
test('F4.6B usa verde semántico para Clasificado',async({page,isMobile})=>{await abrirCentro(page,'posiciones');const estado=isMobile?page.locator('.f4-position-card.qualified .state-clasificado').first():page.locator('.f4-table-wrap .state-clasificado').first();await expect(estado).toBeVisible();const color=await estado.evaluate(e=>getComputedStyle(e).color);expect(color).toBe('rgb(167, 226, 191)')});
test('F4.6B sincroniza los colores de rondas del cuadro integrado',async({page,isMobile})=>{await abrirCentro(page,'cuadro');if(isMobile){const botones=page.locator('.f4-round-tabs button');const cantidad=await botones.count();expect(cantidad).toBeGreaterThan(0);for(let i=0;i<cantidad;i++)await expect(botones.nth(i)).toBeVisible()}else{const rondas=page.locator('.f4-round');await expect(rondas).toHaveCount(2);const primero=await rondas.nth(0).locator(':scope > header').evaluate(e=>getComputedStyle(e).borderBottomColor);const final=await rondas.nth(1).locator(':scope > header').evaluate(e=>getComputedStyle(e).borderBottomColor);expect(primero).not.toBe(final)}});
test('F4.7A publica canonical y noindex en el puente heredado',async({request})=>{const respuesta=await request.get('/torneos?torneo=2');expect(respuesta.ok()).toBeTruthy();const html=await respuesta.text();expect(html).toContain('rel="canonical" href="/w2/torneos"');expect(html).toContain('name="robots" content="noindex, follow"');expect(html).not.toContain('scripts/torneos')});
test('F4.7A los enlaces públicos principales apuntan directamente a W2',async({page})=>{await page.goto('/');const enlaces=page.locator('a[href="/w2/torneos"]');expect(await enlaces.count()).toBeGreaterThan(0);expect(await enlaces.evaluateAll(elementos=>elementos.some(elemento=>{const estilo=getComputedStyle(elemento);const rect=elemento.getBoundingClientRect();return estilo.display!=='none'&&estilo.visibility!=='hidden'&&rect.width>0&&rect.height>0}))).toBeTruthy();await page.goto('/404');const enlace404=page.getByRole('link',{name:'Ver torneos'});await expect(enlace404).toBeVisible();await expect(enlace404).toHaveAttribute('href','/w2/torneos')});
test('F4.7A el sitemap respeta site opcional y nunca publica la ruta heredada',async({request})=>{const respuesta=await request.get('/sitemap.xml');const xml=await respuesta.text();expect(xml).not.toContain('/torneos/');if(xml.includes('<loc>'))expect(xml).toContain('/w2/torneos/')});
test('F4.7A1 el hero del catálogo comienza inmediatamente bajo la cabecera',async({page})=>{await page.goto('/w2/torneos');const header=page.locator('[data-w2-header]');const hero=page.locator('.w2t-hero');await expect(header).toBeVisible();await expect(hero).toBeVisible();const geometria=await page.evaluate(()=>{const h=document.querySelector<HTMLElement>('[data-w2-header]')!.getBoundingClientRect();const hero=document.querySelector<HTMLElement>('.w2t-hero')!.getBoundingClientRect();return {finCabecera:h.bottom,inicioHero:hero.top,brecha:hero.top-h.bottom}});expect(Math.abs(geometria.brecha)).toBeLessThanOrEqual(2)});
test('F4.7A2 compacta el hero y anticipa el calendario',async({page,isMobile})=>{await page.goto('/w2/torneos');const hero=page.locator('.w2t-hero');const calendario=page.locator('.w2t-explorer');await expect(hero).toBeVisible();await expect(calendario).toBeVisible();const medidas=await page.evaluate(()=>{const hero=document.querySelector<HTMLElement>('.w2t-hero')!.getBoundingClientRect();const calendario=document.querySelector<HTMLElement>('.w2t-explorer')!.getBoundingClientRect();return {altoHero:hero.height,inicioCalendario:calendario.top,viewport:innerHeight}});if(!isMobile){expect(medidas.altoHero).toBeLessThanOrEqual(760);expect(medidas.inicioCalendario).toBeLessThanOrEqual(medidas.viewport+120)}else expect(medidas.altoHero).toBeGreaterThan(0)});
test('F4.7A2 publica una nomenclatura directa para el catálogo',async({page})=>{await page.goto('/w2/torneos');await expect(page.getByRole('heading',{name:'Calendario de torneos'})).toBeVisible();await expect(page.locator('.w2t-section-head')).toContainText('Todas las inscripciones se realizan exclusivamente por pareja.');await expect(page.getByRole('heading',{name:'Competencias W2'})).toHaveCount(0)});
test('F4.7A3 el selector conserva un único indicador rojo',async({page,isMobile})=>{await page.goto('/w2/torneos');if(isMobile){await page.locator('#abrirFiltrosTorneos').click();await expect(page.locator('#panelFiltrosTorneos')).toBeVisible()}const rama=page.locator('.w2t-select').filter({has:page.locator('#filtroRama')});await rama.locator('.w2t-select-trigger').click();const menu=rama.locator('.w2t-select-menu');await expect(menu).toBeVisible();const pseudo=await menu.evaluate(e=>getComputedStyle(e,'::before').display);expect(pseudo).toBe('none');await expect(menu.locator('button[aria-selected="true"]')).toBeVisible()});
test('F4.7A4 la llave completa colorea cada partido según su fase',async({page,isMobile})=>{if(isMobile)return;await abrirCentro(page,'cuadro');await page.locator('[data-f4-full-bracket]').click();const modal=page.locator('#modalCuadroTorneo');await expect(modal).toBeVisible();const fases=await modal.locator('.bracket-round').evaluateAll(rondas=>rondas.map(ronda=>{const tarjeta=ronda.querySelector<HTMLElement>('.bracket-card');const rotulo=tarjeta?.querySelector<HTMLElement>(':scope > header > span:first-child,:scope > header > small:first-child');return tarjeta?{borde:getComputedStyle(tarjeta).borderTopColor,rotulo:rotulo?getComputedStyle(rotulo).color:'',nombre:(ronda.querySelector(':scope > header')?.textContent||'').toUpperCase()}:null}).filter(Boolean));expect(fases.length).toBeGreaterThan(1);expect(new Set(fases.map(f=>f!.borde)).size).toBeGreaterThan(1);for(const fase of fases)expect(fase!.rotulo).toBe(fase!.borde)});
test('F4.7A5 los rótulos Octavos, Cuartos, Semifinal y Final heredan el color disponible',async({page,isMobile})=>{if(isMobile)return;await abrirCentro(page,'cuadro');await page.locator('[data-f4-full-bracket]').click();const modal=page.locator('#modalCuadroTorneo');const rondas=modal.locator('.bracket-round');for(let i=0;i<await rondas.count();i++){const ronda=rondas.nth(i);const tarjeta=ronda.locator('.bracket-card').first();const rotulo=tarjeta.locator(':scope > header > span:first-child,:scope > header > small:first-child').first();await expect(rotulo).toBeVisible();expect(await rotulo.evaluate(e=>getComputedStyle(e).color)).toBe(await tarjeta.evaluate(e=>getComputedStyle(e).borderTopColor))}});
test('F4.7C los selectores de Torneos se despliegan hacia abajo',async({page,isMobile})=>{await page.goto('/w2/torneos');if(isMobile){await page.locator('#abrirFiltrosTorneos').click();await expect(page.locator('#panelFiltrosTorneos')).toBeVisible()}for(const id of ['filtroRama','filtroFormato']){const selector=page.locator('.w2t-select').filter({has:page.locator('#'+id)});const trigger=selector.locator('.w2t-select-trigger');await trigger.click();const menu=selector.locator('.w2t-select-menu');await expect(menu).toBeVisible();const geometria=await Promise.all([trigger.evaluate(e=>e.getBoundingClientRect().bottom),menu.evaluate(e=>{const r=e.getBoundingClientRect();return {top:r.top,bottom:r.bottom,viewport:innerHeight}})]);expect(geometria[1].top).toBeGreaterThanOrEqual(geometria[0]-1);expect(geometria[1].bottom).toBeLessThanOrEqual(geometria[1].viewport+1);await page.keyboard.press('Escape')}});

test('R2.1A1 persiste y restaura el estado del catálogo',async({page})=>{await page.goto('/w2/torneos');await page.getByRole('button',{name:/En curso/}).click();await page.locator('#buscarTorneo').fill('Copa');await expect(page).toHaveURL(/estado=EN_CURSO/);await expect(page).toHaveURL(/buscar=Copa/);await page.reload();await expect(page.locator('#buscarTorneo')).toHaveValue('Copa');await expect(page.locator('#listaTorneos')).toContainText('Copa Metropolitana E2E');await page.goBack();await expect(page.locator('#buscarTorneo')).toHaveValue('')});

test('R2.1A1 cachea detalle durante la navegación SPA',async({page})=>{let llamadas=0;page.on('request',r=>{if(r.url().endsWith('/torneos/2'))llamadas++});await page.goto('/w2/torneos?torneo=2');await expect(page.locator('.w2td-detail')).toContainText('Copa Metropolitana E2E');await page.locator('[data-back-catalog]').click();await page.getByRole('button',{name:/En curso/}).click();await page.locator('[data-torneo-id="2"]').first().click();await expect(page.locator('.w2td-detail')).toContainText('Copa Metropolitana E2E');expect(llamadas).toBe(1)});

test('R2.1A2 accesos rápidos y limpieza conservan contrato URL',async({page})=>{await page.goto('/w2/torneos');await page.locator('[data-summary-open]').click();await expect(page).toHaveURL(/inscripcion=abierta/);await page.locator('#limpiarFiltrosTorneosInline').click();await expect(page).not.toHaveURL(/inscripcion=/);await expect(page.locator('#filtroInscripcion')).not.toBeChecked()});

test('R2.1A2 restaura filtros completos desde una URL compartida',async({page,isMobile})=>{await page.goto('/w2/torneos?estado=EN_CURSO&buscar=Copa&rama=MASCULINA&formato=GRUPOS_ELIMINACION');await expect(page.locator('#buscarTorneo')).toHaveValue('Copa');await expect(page.locator('#filtroRama')).toHaveValue('MASCULINA');await expect(page.locator('#filtroFormato')).toHaveValue('GRUPOS_ELIMINACION');await expect(page.locator('#listaTorneos')).toContainText('Copa Metropolitana E2E');if(!isMobile){const ramaPremium=page.locator('.w2t-select').filter({has:page.locator('#filtroRama')});await expect(ramaPremium.locator('.w2t-select-trigger')).toContainText('Libre');await expect(ramaPremium.locator('.w2t-select-menu [aria-selected="true"]')).toContainText('Libre')}});

test('R2.1B diferencia Libre de Mixto en el contrato publico',async({page})=>{await page.goto('/w2/torneos');await page.getByRole('button',{name:/En curso/}).click();const tarjeta=page.locator('.w2t-card').filter({hasText:'Copa Metropolitana E2E'});await expect(tarjeta).toContainText('Libre');await expect(tarjeta).toContainText('Mixto');await expect(tarjeta).not.toContainText('Abierto');await expect(tarjeta).not.toContainText('Masculina')});

test('R2.1B conserva valores heredados en URL pero publica Libre',async({page,isMobile})=>{await page.goto('/w2/torneos?estado=EN_CURSO&rama=MASCULINA');await expect(page.locator('#filtroRama')).toHaveValue('MASCULINA');if(isMobile)await page.locator('#abrirFiltrosTorneos').click();const rama=page.locator('.w2t-select').filter({has:page.locator('#filtroRama')});await expect(rama.locator('.w2t-select-trigger')).toContainText('Libre');await expect(page).toHaveURL(/rama=MASCULINA/)});

test('R2.1C1 conserva vocabulario y búsqueda tras extraer el dominio compartido',async({page})=>{await page.goto('/w2/torneos?estado=EN_CURSO&buscar=metropolitana&rama=MASCULINA');await expect(page.locator('#listaTorneos')).toContainText('Copa Metropolitana E2E');await expect(page.locator('.w2t-card').filter({hasText:'Copa Metropolitana E2E'})).toContainText('Libre');await expect(page.locator('#filtroRama')).toHaveValue('MASCULINA')});

test('R2.1C2 conserva el contrato URL tras extraer el estado del catálogo',async({page})=>{await page.goto('/w2/torneos?estado=EN_CURSO&buscar=Copa&rama=MASCULINA&formato=GRUPOS_ELIMINACION');await expect(page.locator('#buscarTorneo')).toHaveValue('Copa');await expect(page.locator('#filtroRama')).toHaveValue('MASCULINA');await expect(page.locator('#filtroFormato')).toHaveValue('GRUPOS_ELIMINACION');await page.locator('#limpiarFiltrosTorneosInline').click();await expect(page).not.toHaveURL(/buscar=|rama=|formato=/)});

test('R2.1C2V alinea tarjetas con nombres y descripciones de distinta longitud',async({page})=>{await page.route('**/api/publica/torneos',async route=>{if(route.request().method()!=='GET')return route.fallback();const base={fechaInicio:'2026-12-01',fechaFin:'2026-12-03',estadoPortal:'PROXIMO',estado:'PUBLICADO',inscripcionDisponible:false,cantidadCategorias:1,categorias:['4ta'],ramas:['MASCULINA'],formatos:['GRUPOS_ELIMINACION'],precioMinimo:25000,precioMaximo:25000,cupoTotal:16,parejasConfirmadas:8,cuposDisponibles:8,partidosTotales:0,partidosFinalizados:0};await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify([{...base,id:101,nombre:'Copa',descripcion:''},{...base,id:102,nombre:'Torneo Metropolitano de Primavera y Aniversario',descripcion:'Descripción breve.'},{...base,id:103,nombre:'Copa Regional de Parejas Categoría Libre',descripcion:'Una descripción deliberadamente extensa que debe limitarse a dos líneas sin desplazar las métricas ni la acción inferior.'}])})});await page.goto('/w2/torneos');const cards=page.locator('.w2t-card');await expect(cards).toHaveCount(3);const geometria=await cards.evaluateAll(items=>items.map(card=>{const cardRect=card.getBoundingClientRect(),title=card.querySelector<HTMLElement>('h3')!,tags=card.querySelector<HTMLElement>('.w2t-tags')!,facts=card.querySelector<HTMLElement>('.w2t-facts')!,action=card.querySelector<HTMLElement>(':scope > footer')!;return {cardHeight:cardRect.height,titleHeight:title.getBoundingClientRect().height,tagsOffset:tags.getBoundingClientRect().top-cardRect.top,factsOffset:facts.getBoundingClientRect().top-cardRect.top,actionOffset:action.getBoundingClientRect().top-cardRect.top}}));for(const key of ['cardHeight','titleHeight','tagsOffset','factsOffset','actionOffset'] as const){const values=geometria.map(x=>x[key]);expect(Math.max(...values)-Math.min(...values)).toBeLessThanOrEqual(2)}});

test('R2.1C3 conserva la adaptación tolerante del catálogo público',async({page})=>{await page.route('**/api/publica/torneos',async route=>{if(route.request().method()!=='GET')return route.fallback();await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify([{id:901,nombre:'Torneo Adaptado',descripcion:null,fechaInicio:'2026-12-10',fechaFin:'2026-12-12',estado:'PUBLICADO',inscripcionDisponible:false,categorias:null,ramas:['MASCULINA'],formatos:['ELIMINACION_DIRECTA'],cantidadCategorias:'1',cupoTotal:'16',parejasConfirmadas:'4',cuposDisponibles:'12',precioMinimo:'25000',precioMaximo:'25000'}])})});await page.goto('/w2/torneos');const tarjeta=page.locator('.w2t-card').filter({hasText:'Torneo Adaptado'});await expect(tarjeta).toBeVisible();await expect(tarjeta).toContainText('Libre');await expect(tarjeta).toContainText('$ 25.000');await expect(tarjeta).toContainText('12 cupos')});

test('R2.1C4 descarta una carga de detalle obsoleta',async({page})=>{await page.route('**/api/publica/torneos/1',async route=>{await new Promise(resolve=>setTimeout(resolve,350));try{await route.fallback()}catch{}});await page.goto('/w2/torneos');await expect(page.locator('.w2t-card').first()).toBeVisible();await page.evaluate(()=>{const lista=document.getElementById('listaTorneos');if(!lista)throw new Error('No existe listaTorneos');const crear=(id:number)=>{const boton=document.createElement('button');boton.type='button';boton.className='catalog-open';boton.dataset.torneoId=String(id);lista.appendChild(boton);return boton};const primero=crear(1),segundo=crear(2);primero.click();segundo.click();primero.remove();segundo.remove()});await expect(page).toHaveURL(/torneo=2/);await expect(page.locator('.w2td-detail')).toContainText('Copa Metropolitana E2E');await page.waitForTimeout(450);await expect(page).toHaveURL(/torneo=2/);await expect(page.locator('.w2td-detail')).toContainText('Copa Metropolitana E2E')});
test('R2.1C4 mantiene cache de catalogo durante la sesion SPA',async({page})=>{let llamadas=0;page.on('request',request=>{if(new URL(request.url()).pathname.endsWith('/api/publica/torneos'))llamadas++});await page.goto('/w2/torneos');await expect(page.locator('.w2t-card').first()).toBeVisible();await page.locator('.w2t-card').first().getByRole('button').last().click();await page.locator('[data-back-catalog]').click();expect(llamadas).toBe(1)});

test('R2.1C5 conserva la presentacion modular del detalle y sus pestanas',async({page})=>{await page.goto('/w2/torneos?torneo=1&seccion=categorias');await expect(page.locator('.premium-tournament-detail')).toBeVisible();await expect(page.locator('[data-detail-tab="categorias"]')).toHaveAttribute('aria-selected','true');await expect(page.locator('.premium-category-card')).toHaveCount(1);await expect(page.locator('.premium-category-card').first()).toContainText('Inscripción por pareja');await page.locator('[data-detail-tab="reglamento"]').click();await expect(page).toHaveURL(/seccion=reglamento/);await expect(page.locator('.premium-rules-panel')).toBeVisible()});

test('R2.1C5V2 vuelve al inicio visible del estado activo',async({page})=>{for(const estado of ['PROXIMO','EN_CURSO','FINALIZADO']){const query=estado==='PROXIMO'?'':'?estado='+estado;await page.goto('/w2/torneos'+query);const tarjeta=page.locator('#listaTorneos .w2t-card').last();await expect(tarjeta).toBeVisible();await tarjeta.scrollIntoViewIfNeeded();await tarjeta.locator('.catalog-open').click();await expect(page.locator('.premium-tournament-detail')).toBeVisible();await page.locator('[data-back-catalog]').click();const ancla=page.locator('#pestanasTorneos');await expect(ancla).toBeVisible();await expect.poll(async()=>page.evaluate(()=>{const ancla=document.getElementById('pestanasTorneos')!,cabecera=document.querySelector<HTMLElement>('[data-w2-header],header[data-site-header]');return Math.abs(ancla.getBoundingClientRect().top-(cabecera?.getBoundingClientRect().height||0))}),{timeout:4000}).toBeLessThanOrEqual(24);await expect(page).toHaveURL(estado==='PROXIMO'?/\/w2\/torneos(?:\?|$)/:new RegExp('estado='+estado))}});
test('R2.1C6 conserva la presentacion modular del catalogo',async({page})=>{await page.goto('/w2/torneos');await expect(page.locator('#torneoDestacado')).toContainText('Torneo E2E');await expect(page.locator('#pestanasTorneos [data-catalog-state="PROXIMO"]')).toHaveClass(/active/);const tarjeta=page.locator('#listaTorneos .w2t-card').first();await expect(tarjeta).toContainText('Inscripción por pareja');await expect(tarjeta).toContainText('Femenino');await expect(tarjeta).toContainText('Grupos + eliminación');await page.locator('#buscarTorneo').fill('inexistente');await expect(page.locator('.w2t-empty')).toBeVisible();await page.locator('#vaciarFiltrosTorneos').click();await expect(tarjeta).toBeVisible()});

test('R2.1C6V3 mantiene opaca la union entre cabecera y navegacion competitiva',async({page})=>{await abrirCentro(page,'partidos');const nav=page.locator('#detalleTorneoHost .f4-center > nav.f4-nav');await expect(nav).toBeVisible();await page.evaluate(()=>scrollTo(0,document.body.scrollHeight));const resultado=await nav.evaluate(elemento=>{const estilo=getComputedStyle(elemento),cubierta=getComputedStyle(elemento,'::before'),boton=elemento.querySelector<HTMLElement>('button'),control=boton?getComputedStyle(boton):null;return {fondoImagen:estilo.backgroundImage,fondoColor:estilo.backgroundColor,sombra:estilo.boxShadow,margen:parseFloat(estilo.marginTop),posicion:estilo.position,z:estilo.zIndex,cubiertaDisplay:cubierta.display,cubiertaAlto:parseFloat(cubierta.height),cubiertaFondo:cubierta.backgroundColor,cubiertaZ:cubierta.zIndex,controlZ:control?.zIndex||''}});expect(resultado.posicion).toBe('sticky');expect(resultado.margen).toBeGreaterThanOrEqual(7);expect(resultado.margen).toBeLessThanOrEqual(10);expect(Number(resultado.z)).toBeGreaterThan(100);expect(resultado.fondoImagen).toContain('linear-gradient');expect(resultado.sombra).not.toBe('none');expect(resultado.cubiertaDisplay).toBe('block');expect(resultado.cubiertaAlto).toBeGreaterThanOrEqual(6);expect(resultado.cubiertaAlto).toBeLessThanOrEqual(12);expect(resultado.cubiertaFondo).not.toBe('rgba(0, 0, 0, 0)');expect(Number(resultado.cubiertaZ)).toBeLessThan(Number(resultado.controlZ))});
test('R2.1C7 conserva accesos rapidos, filtros y selector tras extraer la interaccion',async({page,isMobile})=>{await page.goto('/w2/torneos');await page.locator('[data-summary-open]').click();await expect(page).toHaveURL(/inscripcion=abierta/);await expect(page.locator('#filtroInscripcion')).toBeChecked();if(isMobile){await page.locator('#abrirFiltrosTorneos').click();await expect(page.locator('#panelFiltrosTorneos')).toHaveClass(/open/);await expect(page.locator('#panelFiltrosTorneos')).not.toHaveAttribute('inert');await page.keyboard.press('Escape');await expect(page.locator('#panelFiltrosTorneos')).not.toHaveClass(/open/)}else{const rama=page.locator('.w2t-select').filter({has:page.locator('#filtroRama')});await rama.locator('.w2t-select-trigger').click();await expect(rama.locator('.w2t-select-menu')).toBeVisible();await page.keyboard.press('End');await page.keyboard.press('Enter');await expect(page.locator('#filtroRama')).toHaveValue('MIXTA');await expect(page).toHaveURL(/rama=MIXTA/)}});
test('R2.1C8 conserva validacion, envio y confirmacion de la inscripcion por pareja',async({page})=>{let body:any;page.on('request',r=>{if(r.url().endsWith('/torneos/inscripciones')&&r.method()==='POST')body=r.postDataJSON()});await page.goto('/w2/torneos?torneo=1&seccion=categorias');await page.locator('.inscribir-pareja').click();await expect(page.locator('#modalInscripcion')).toBeVisible();await page.locator('#enviarInscripcion').click();await expect(page.locator('#responsableNombre')).toBeFocused();await page.locator('#responsableNombre').fill('Facundo');await page.locator('#responsableApellido').fill('Vitale');await page.locator('#responsableTelefono').fill('1144445555');await page.locator('#parejaNombre').fill('Jugador');await page.locator('#parejaApellido').fill('E2E');await page.locator('#parejaTelefono').fill('1166667777');await page.locator('#comentariosInscripcion').fill('R2.1C8');await page.locator('#enviarInscripcion').click();await expect(page.locator('#exitoInscripcion')).toContainText('#801');expect(body.torneoCategoriaId).toBe(11);expect(body.comentarios).toBe('R2.1C8');await page.locator('#cerrarExitoInscripcion').click();await expect(page.locator('#modalInscripcion')).toHaveClass(/hidden/)});
test('R2.1C9 conserva detalle, pestanas y retorno desde el centro competitivo',async({page})=>{await page.goto('/w2/torneos?torneo=2');await expect(page.locator('.w2td-detail')).toContainText('Copa Metropolitana E2E');await page.locator('[data-detail-tab="categorias"]').click();await expect(page).toHaveURL(/seccion=categorias/);await expect(page.locator('.premium-category-card')).toHaveCount(2);await page.locator('[data-open-competition="11"]').click();await expect(page.locator('.f4-center')).toBeVisible();await page.locator('[data-f4-back]').click();await expect(page.locator('[data-detail-tab="categorias"]')).toHaveAttribute('aria-selected','true');await expect(page).not.toHaveURL(/categoria=|vista=/);await page.locator('[data-back-catalog]').click();await expect(page.locator('#vistaCatalogoTorneos')).toBeVisible();await expect(page).not.toHaveURL(/torneo=/)});
