test('R2.2A2D diferencia finalizados con acento historico',async({page})=>{await page.goto('/w2/torneos?estado=FINALIZADO');const tarjeta=page.locator('.w2t-card.state-finalizado').first();await expect(tarjeta).toBeVisible();const colores=await tarjeta.evaluate(elemento=>{const estado=elemento.querySelector<HTMLElement>('.w2t-status')!,etiqueta=elemento.querySelector<HTMLElement>('.w2t-tags span')!,barra=elemento.querySelector<HTMLElement>('.w2t-progress span span');return {estado:getComputedStyle(estado).color,etiqueta:getComputedStyle(etiqueta).borderColor,barra:barra?getComputedStyle(barra).backgroundImage:''}});expect(colores.estado).not.toBe('rgb(217, 223, 220)');expect(colores.etiqueta).not.toBe('rgb(48, 56, 62)');if(colores.barra)expect(colores.barra).toContain('linear-gradient')});
test('R2.2A2D compacta finalizados sin perder alineacion',async({page,isMobile})=>{await page.route('**/api/publica/torneos',async route=>{const base={fechaInicio:'2026-10-10',fechaFin:'2026-10-12',estado:'FINALIZADO',estadoPortal:'FINALIZADO',etapaCompetitiva:'FINALIZADA',inscripcionDisponible:false,cantidadCategorias:1,categorias:['4ta'],ramas:['LIBRE'],formatos:['ELIMINACION_DIRECTA'],parejasConfirmadas:8,partidosTotales:4,partidosFinalizados:4,resultadosDisponibles:true};await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify([{...base,id:996,nombre:'Final Breve',descripcion:''},{...base,id:997,nombre:'Final Metropolitana de Parejas',descripcion:'Descripción histórica breve.'},{...base,id:998,nombre:'Final Regional de Primavera y Aniversario',descripcion:''}])})});await page.goto('/w2/torneos?estado=FINALIZADO');const tarjetas=page.locator('.w2t-card.state-finalizado');await expect(tarjetas).toHaveCount(3);const medidas=await tarjetas.evaluateAll(items=>items.map(card=>{const r=card.getBoundingClientRect(),footer=card.querySelector<HTMLElement>(':scope > footer')!.getBoundingClientRect();return {alto:r.height,accion:footer.top-r.top}}));if(!isMobile){expect(Math.max(...medidas.map(x=>x.alto))-Math.min(...medidas.map(x=>x.alto))).toBeLessThanOrEqual(2);expect(Math.max(...medidas.map(x=>x.accion))-Math.min(...medidas.map(x=>x.accion))).toBeLessThanOrEqual(2)}else{expect(medidas.every(x=>x.alto>0&&x.accion>0)).toBeTruthy();const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-innerWidth);expect(overflow).toBeLessThanOrEqual(1)}});
