test('R2.2C1 compacta hero y estabiliza navegacion',async({page})=>{await abrirCentro(page);const hero=page.locator('.w2cc-hero'),nav=page.locator('.w2cc-center .f4-nav');await expect(hero).toBeVisible();await expect(nav).toBeVisible();const g=await page.evaluate(()=>{const h=document.querySelector<HTMLElement>('.w2cc-hero')!.getBoundingClientRect(),n=document.querySelector<HTMLElement>('.w2cc-center .f4-nav')!.getBoundingClientRect();return {hero:h.height,nav:n.height,overflow:document.documentElement.scrollWidth-innerWidth}});expect(g.hero).toBeLessThanOrEqual(382);expect(g.nav).toBeGreaterThanOrEqual(44);expect(g.overflow).toBeLessThanOrEqual(1)});
test('R2.2C1 moderniza resumen y acciones contextuales',async({page})=>{await abrirCentro(page);const resumen=page.locator('.w2cc-overview');await expect(resumen).toContainText('Estado general de la competencia');await expect(resumen).toContainText('Ver agenda completa');await expect(resumen).toContainText('Ver todos los resultados');await expect(resumen).not.toContainText('Todo el torneo, en una sola vista')});
test('R2.2C1 refina posiciones y tabla segura',async({page,isMobile})=>{await abrirCentro(page,'posiciones');await expect(page.locator('.f4-standings-status')).toContainText(/Posiciones definitivas|Posiciones provisorias|Desempate pendiente/);await expect(page.locator('.f4-qualification-note')).toContainText('Clasifican');if(isMobile)await expect(page.locator('.f4-positions-mobile')).toBeVisible();else{await expect(page.locator('.f4-table-wrap')).toBeVisible();const ancho=await page.locator('.f4-table-wrap table').evaluate(e=>e.getBoundingClientRect().width);expect(ancho).toBeGreaterThanOrEqual(880)}});
test('R2.2C1 contextualiza pendientes y finalistas',async({page})=>{await abrirCentro(page,'partidos');await page.locator('[data-f4-phase="fase-final"]').click();const final=page.locator('.f4-phase-section');await expect(final).toContainText('Final pendiente');await expect(final).toContainText('Ganador de Semifinal');await expect(final).toContainText(/Fecha y horario por definir|18 de octubre de 2026 · 20:00 · Cancha E2E/);await expect(final.locator('.pending-slot')).toHaveCount(1)});
test('R2.2C1 alinea cuadro y mejora llave completa accesible',async({page,isMobile})=>{await abrirCentro(page,'cuadro');await expect(page.locator('.f4-rounds')).toBeVisible();if(isMobile){await expect(page.locator('.f4-round-tabs')).toBeVisible();return}await page.locator('[data-f4-full-bracket]').click();const modal=page.locator('#modalCuadroTorneo');await expect(modal).toHaveAttribute('role','dialog');await expect(modal).toHaveAttribute('aria-modal','true');await expect(page.locator('#escalaLlave')).toContainText(/7d%|8d%|90%/);await page.keyboard.press('Escape');await expect(modal).toHaveClass(/hidden/);await expect(page.locator('[data-f4-full-bracket]')).toBeFocused()});

test('R2.2C2 moderniza la navegacion flotante',async({page})=>{await abrirCentro(page);const nav=page.locator('.w2cc-center .f4-nav');await expect(nav).toBeVisible();const estilo=await nav.evaluate(e=>{const s=getComputedStyle(e);return {radio:s.borderRadius,fondo:s.backgroundImage,borde:s.borderColor,gap:s.gap}});expect(parseFloat(estilo.radio)).toBeGreaterThanOrEqual(14);expect(estilo.fondo).toContain('linear-gradient');expect(estilo.borde).not.toBe('rgba(0, 0, 0, 0)');expect(parseFloat(estilo.gap)).toBeGreaterThan(0)});
test('R2.2C2 elimina divisores y eleva la pestana activa',async({page})=>{await abrirCentro(page,'partidos');const botones=page.locator('.w2cc-center .f4-nav button');await expect(botones).toHaveCount(4);const bordes=await botones.evaluateAll(items=>items.map(e=>{const s=getComputedStyle(e);return {activo:e.classList.contains('active'),izquierdo:s.borderLeftColor,derecho:s.borderRightColor}}));expect(bordes.filter(x=>!x.activo).every(x=>x.izquierdo==='rgba(0, 0, 0, 0)')).toBeTruthy();expect(bordes.filter(x=>x.activo).every(x=>x.izquierdo===x.derecho)).toBeTruthy();const activo=page.locator('.w2cc-center .f4-nav button.active');const estilo=await activo.evaluate(e=>{const s=getComputedStyle(e),a=getComputedStyle(e,'::after');return {radio:s.borderRadius,fondo:s.backgroundImage,indicador:a.width,indicadorRadio:a.borderRadius}});expect(parseFloat(estilo.radio)).toBeGreaterThanOrEqual(10);expect(estilo.fondo).toContain('linear-gradient');expect(parseFloat(estilo.indicador)).toBeLessThanOrEqual(40);expect(parseFloat(estilo.indicadorRadio)).toBeGreaterThan(0)});
test('R2.2C2 conserva sticky opaco y contenido visible',async({page})=>{await abrirCentro(page,'partidos');await page.evaluate(()=>scrollTo(0,document.body.scrollHeight/2));const nav=page.locator('.w2cc-center .f4-nav');const datos=await nav.evaluate(e=>{const s=getComputedStyle(e),b=getComputedStyle(e,'::before');return {posicion:s.position,z:Number(s.zIndex),fondo:s.backgroundImage,cubierta:b.display,cubiertaFondo:b.backgroundColor,cubiertaAlto:parseFloat(b.height),overflow:document.documentElement.scrollWidth-innerWidth}});expect(datos.posicion).toBe('sticky');expect(datos.z).toBeGreaterThan(100);expect(datos.fondo).toContain('linear-gradient');expect(datos.cubierta).toBe('block');expect(datos.cubiertaFondo).not.toBe('rgba(0, 0, 0, 0)');expect(datos.cubiertaAlto).toBeLessThanOrEqual(12);expect(datos.overflow).toBeLessThanOrEqual(1)});

test('R2.2C2 limita la cubierta sticky sin cortar el hero',async({page})=>{await abrirCentro(page,'partidos');const nav=page.locator('.w2cc-center .f4-nav'),hero=page.locator('.w2cc-hero');await expect(nav).toBeVisible();await expect(hero).toBeVisible();const g=await page.evaluate(()=>{const n=document.querySelector<HTMLElement>('.w2cc-center .f4-nav')!,h=document.querySelector<HTMLElement>('.w2cc-hero')!,p=getComputedStyle(n,'::before'),nr=n.getBoundingClientRect(),hr=h.getBoundingClientRect();return {cubierta:parseFloat(p.height),cubiertaTop:parseFloat(p.top),brecha:nr.top-hr.bottom,heroVisible:hr.height,overflow:document.documentElement.scrollWidth-innerWidth}});expect(g.cubierta).toBeGreaterThanOrEqual(6);expect(g.cubierta).toBeLessThanOrEqual(12);expect(g.cubiertaTop).toBeGreaterThanOrEqual(-12);expect(g.brecha).toBeGreaterThanOrEqual(0);expect(g.brecha).toBeLessThanOrEqual(30);expect(g.heroVisible).toBeGreaterThan(0);expect(g.overflow).toBeLessThanOrEqual(1)});
test('R2.2C2 conserva cubierta opaca al adherirse',async({page})=>{await abrirCentro(page,'partidos');await page.evaluate(()=>scrollTo(0,document.body.scrollHeight/2));const nav=page.locator('.w2cc-center .f4-nav');const datos=await nav.evaluate(e=>{const s=getComputedStyle(e),p=getComputedStyle(e,'::before');return {posicion:s.position,alto:parseFloat(p.height),fondo:p.backgroundColor,display:p.display}});expect(datos.posicion).toBe('sticky');expect(datos.display).toBe('block');expect(datos.alto).toBeLessThanOrEqual(12);expect(datos.fondo).not.toBe('rgba(0, 0, 0, 0)')});
test('R2.2C3 estabiliza el detalle sin depender de route fetch',async({page})=>{await page.route('**/api/publica/torneos/2',async route=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(detalleTorneoPrueba({etapaCompetitiva:'PREPARACION',partidosTotales:undefined,partidosFinalizados:undefined}))}));await page.goto('/w2/torneos?torneo=2');await expect(page.locator('.w2td-detail')).toBeVisible();await expect(page.locator('.w2td-summary')).toContainText('Instancia');await expect(page.locator('.w2td-detail')).not.toContainText('undefined')});
test('R2.2C3 conserva categoria iniciada y partidos en informacion',async({page})=>{await page.goto('/w2/torneos?torneo=2&seccion=categorias');const categoria=page.locator('.w2td-category').first();await expect(categoria).toContainText('Libre');await expect(categoria).toContainText(/Competencia iniciada|Inscripción por pareja/);await page.locator('[data-detail-tab="informacion"]').click();await expect(page.locator('.w2td-information')).toContainText(/Partidos registrados|Todavía sin actividad|[0-9]+\s*\/\s*[0-9]+/)});
// R2.2C4 alinea regresiones historicas con el contrato visual vigente.
// R2.2C5 estabiliza geometria del detalle esperando cada superficie antes de medir.
